1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.util.AddressNormalizer;
6	import org.springframework.web.bind.annotation.RequestBody;
7	
8	/**
9	 * First step of the create-owner pipeline: reads the request body once, normalizes its
10	 * address to canonical form (see {@link AddressNormalizer}) and republishes the body so
11	 * downstream steps consume it as {@code @Val}. Running before {@link ValidateOwnerFields}
12	 * means the required-field check sees the normalized address, so an address that is blank
13	 * only after normalization is rejected; and because {@link BuildOwner} stores the same
14	 * value, the persisted and returned address is the normalized one. Household comparison
15	 * (see {@link Households}) then works from the normalized form too.
16	 */
17	public class NormalizeOwnerAddress {
18	
19	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> normalized) {
20	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
21	        normalized.set(request);
22	    }
23	}
