3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create-owner request that would share a household (same last name and same
10	 * address) with an existing owner, responding 409. Last name and address are compared
11	 * case-insensitively with collapsed whitespace (see {@link Households}). A request may
12	 * opt in to sharing a household by setting {@code sharesHousehold} true, in which case
13	 * the check is skipped and {@link AssignHouseholdId} links the owners instead.
14	 */
15	public class EnsureUniqueHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
20	            return;
21	        }
22	        if (!Households.membersOf(ownerRepository, request.getLastName(), request.getAddress()).isEmpty()) {
23	            throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
24	        }
25	    }
26	}
