3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	
10	/**
11	 * Normalizes an owner request's optional email: when present it must be a syntactically
12	 * valid address, otherwise the request is rejected with a 400. A valid address is stored
13	 * lower-cased. Mutates the shared request in place so downstream steps ({@link BuildOwner}
14	 * / {@link ApplyOwner}) persist the normalized value. Absent or blank email is left
15	 * untouched, since the field is optional.
16	 */
17	public class NormalizeOwnerEmail {
18	
19	    /** Syntactic check: a non-empty local part, an '@', and a dotted domain, no whitespace. */
20	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
21	
22	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
23	        String email = request.getEmail();
24	        if (email == null || email.isBlank()) {
25	            return;
26	        }
27	        if (!EMAIL.matcher(email).matches()) {
28	            throw new InvalidEmailException(email);
29	        }
30	        request.setEmail(email.toLowerCase(Locale.ROOT));
31	    }
32	}
