3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the new owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}:
11	 * the upper-cased first three letters of the city, a hyphen, the upper-cased first three
12	 * letters of the last name, a hyphen, and a per-city 4-digit zero-padded sequence equal to
13	 * one more than the number of owners already in that city (e.g. {@code FRA-SMI-0007}). Runs
14	 * after {@link BuildOwner} (so the entity, its city and last name exist) and before
15	 * {@link SaveOwner} persists the code.
16	 */
17	public class AssignOwnerCustomerCode {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        long sequence = Cities.countIn(ownerRepository, owner.getCity()) + 1;
21	        owner.setCustomerCode(String.format("%s-%s-%04d",
22	                prefix(owner.getCity()), prefix(owner.getLastName()), sequence));
23	    }
24	
25	    private static String prefix(String value) {
26	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
27	    }
28	}
